INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20D1FF5', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The function $p(t) = 200 \\cdot (0.85)^t$ models the amount, in milligrams, of a substance remaining after $t$ hours. By what percent does the substance decrease each hour?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15', ARRAY['15'], E'In the exponential decay model $p(t) = 200 \\cdot (0.85)^t$, the base $0.85$ represents the fraction of the substance remaining after each hour. Since $0.85 = 1 - 0.15$, the substance retains $85\\%$ of its amount each hour, meaning it decreases by $15\\%$ per hour. A common error is reporting $85$ (the percent remaining) rather than $15$ (the percent decrease). Another error is computing $200 \\times 0.15 = 30$ and reporting the absolute decrease in the first hour rather than the percentage rate.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21VOEW8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher takes a random sample of 130 teenagers in a city and finds that their mean daily screen time is $4.7$ hours with a margin of error of $0.6$ hours at the $95\\%$ confidence level. Which of the following conclusions is best supported?', NULL, $lyceon_json$[{"key":"A","text":"$95\\%$ of all teenagers in the city have a daily screen time between $4.1$ and $5.3$ hours."},{"key":"B","text":"There is a $95\\%$ probability that the true mean daily screen time is between $4.1$ and $5.3$ hours."},{"key":"C","text":"The researcher is $95\\%$ confident that the mean daily screen time for all teenagers in the city is between $4.1$ and $5.3$ hours."},{"key":"D","text":"If the study were repeated, $95\\%$ of the teenagers sampled would report between $4.1$ and $5.3$ hours of screen time."}]$lyceon_json$::jsonb, 'C', NULL, E'A $95\\%$ confidence interval means that the method used to construct the interval captures the true population mean $95\\%$ of the time across repeated sampling. The interval $4.7 \\pm 0.6$, or $4.1$ to $5.3$ hours, estimates the population mean, so the researcher is $95\\%$ confident the true mean falls in this range. The distractor claiming $95\\%$ of all teenagers fall in this range confuses a confidence interval for the mean with the distribution of individual values. The distractor stating a $95\\%$ probability that the true mean is in the interval is a common misinterpretation — the true mean is a fixed value, not a random variable; the interval either contains it or does not. The distractor about $95\\%$ of future sampled teenagers confuses the confidence interval with a prediction interval for individual observations.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21YDABH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A cone is inscribed in a hemisphere so that the base of the cone coincides with the flat circular face of the hemisphere. The hemisphere has a radius of $5$. What is the volume of the region inside the hemisphere but outside the cone?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{125\\pi}{3}$"},{"key":"B","text":"$\\frac{250\\pi}{3}$"},{"key":"C","text":"$\\frac{500\\pi}{3}$"},{"key":"D","text":"$125\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The hemisphere has radius $5$, so its volume is $\\frac{2}{3}\\pi r^3 = \\frac{2}{3}\\pi(125) = \\frac{250\\pi}{3}$. The inscribed cone shares the hemisphere''s circular base (radius $5$) and has height equal to the radius ($5$), so its volume is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(25)(5) = \\frac{125\\pi}{3}$. The region inside the hemisphere but outside the cone has volume $\\frac{250\\pi}{3} - \\frac{125\\pi}{3} = \\frac{125\\pi}{3}$. The distractor $\\frac{250\\pi}{3}$ is the hemisphere volume alone, from a student who computes the hemisphere volume but forgets to subtract the cone. The distractor $\\frac{500\\pi}{3}$ equals $\\frac{4}{3}\\pi(5)^3$, the volume of a full sphere, from confusing a hemisphere with a complete sphere. The distractor $125\\pi$ results from subtracting the cone from a full sphere instead of a hemisphere: $\\frac{500\\pi}{3} - \\frac{125\\pi}{3} = \\frac{375\\pi}{3} = 125\\pi$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23HFM38', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $3x + 4y = 44$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{3}{4}$"},{"key":"B","text":"$3$"},{"key":"C","text":"$11$"},{"key":"D","text":"$44$"}]$lyceon_json$::jsonb, 'C', NULL, E'The $y$-intercept occurs where $x = 0$. Substituting $x = 0$ into $3(0) + 4y = 44$ gives $4y = 44$, so $y = 11$. The value $-\\frac{3}{4}$ is the slope of the line (from rewriting as $y = -\\frac{3}{4}x + 11$), not the $y$-intercept. The value $3$ is the coefficient of $x$ in the equation, not the intercept. The value $44$ is the constant on the right side of the equation before dividing by $4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23JTQXR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'The equation $y = 3.5x + 22$ models the relationship between the number of weeks since a plant was purchased, $x$, and the height of the plant, $y$, in centimeters. What is the best interpretation of the number $3.5$ in this equation?', NULL, $lyceon_json$[{"key":"A","text":"The plant was $3.5$ centimeters tall when it was purchased."},{"key":"B","text":"The plant grows $3.5$ centimeters each week."},{"key":"C","text":"The plant will reach a maximum height of $3.5$ centimeters."},{"key":"D","text":"For every $3.5$ weeks, the plant grows $1$ centimeter."}]$lyceon_json$::jsonb, 'B', NULL, E'In the equation $y = 3.5x + 22$, the coefficient $3.5$ is the slope, representing the rate of change: the plant grows $3.5$ centimeters per week. The interpretation that the plant was $3.5$ centimeters tall when purchased confuses the slope with the $y$-intercept; the initial height is $22$ centimeters. The claim that $3.5$ centimeters is a maximum height misinterprets the slope of a linear model as a bound. The statement that the plant grows $1$ centimeter every $3.5$ weeks inverts the rate, interpreting the slope as $\\frac{1}{3.5}$ centimeters per week instead of $3.5$ centimeters per week.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM245UEHV', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{18x^5y^3 - 12x^2y^4}{6x^2y^2}$?', NULL, $lyceon_json$[{"key":"A","text":"$3x^3y - 2y^2$"},{"key":"B","text":"$3x^3y - 12x^2y^4$"},{"key":"C","text":"$3x^5y^3 - 2y^2$"},{"key":"D","text":"$3x^3y + 2y^2$"}]$lyceon_json$::jsonb, 'A', NULL, E'Divide each term in the numerator by the denominator separately. For the first term: $\\frac{18x^5y^3}{6x^2y^2} = 3x^{5-2}y^{3-2} = 3x^3y$. For the second term: $\\frac{12x^2y^4}{6x^2y^2} = 2x^{2-2}y^{4-2} = 2y^2$. Since the original has subtraction, the result is $3x^3y - 2y^2$. The distractor $3x^3y - 12x^2y^4$ results from dividing only the first term by the denominator and leaving the second term unchanged. The distractor $3x^5y^3 - 2y^2$ results from failing to subtract the exponents on $x$ and $y$ in the first term. The distractor $3x^3y + 2y^2$ results from incorrectly changing the subtraction sign to addition when dividing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24O6S8F', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A bakery uses $7$ cups of flour for every $3$ cups of sugar in a cake recipe. If a baker uses $15$ cups of sugar, how many cups of flour are needed?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$21$"},{"key":"C","text":"$35$"},{"key":"D","text":"$45$"}]$lyceon_json$::jsonb, 'C', NULL, E'The ratio of flour to sugar is $\\frac{7}{3}$. Setting up the proportion $\\frac{7}{3} = \\frac{x}{15}$ gives $x = \\frac{7 \\times 15}{3} = \\frac{105}{3} = 35$. The answer $5$ results from dividing $15$ by $3$ but not multiplying by $7$, completing only part of the calculation. The answer $21$ comes from multiplying $7 \\times 3 = 21$, incorrectly combining the ratio values instead of using the proportion. The answer $45$ results from multiplying $3 \\times 15 = 45$, inverting the ratio and applying the sugar-to-sugar product as if it were flour.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25B2AQI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $PQR$ with the right angle at $R$, $PR = 4$ and $QR = 6$. Point $S$ is on hypotenuse $\\overline{PQ}$ such that $\\overline{RS} \\perp \\overline{PQ}$. What is the length of $RS$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{6\\sqrt{13}}{13}$"},{"key":"B","text":"$\\frac{12\\sqrt{13}}{13}$"},{"key":"C","text":"$\\sqrt{10}$"},{"key":"D","text":"$\\frac{24\\sqrt{13}}{13}$"}]$lyceon_json$::jsonb, 'B', NULL, E'First, find $PQ = \\sqrt{PR^2 + QR^2} = \\sqrt{16 + 36} = \\sqrt{52} = 2\\sqrt{13}$. The area of $\\triangle PQR$ can be computed two ways: $\\frac{1}{2}(PR)(QR) = \\frac{1}{2}(4)(6) = 12$, and also $\\frac{1}{2}(PQ)(RS) = \\frac{1}{2}(2\\sqrt{13})(RS)$. Setting these equal: $12 = \\sqrt{13} \\cdot RS$, so $RS = \\frac{12}{\\sqrt{13}} = \\frac{12\\sqrt{13}}{13}$. The distractor $\\frac{6\\sqrt{13}}{13}$ results from omitting the $\\frac{1}{2}$ factor in the second area expression, writing area $= PQ \\cdot RS$ instead of $\\frac{1}{2} \\cdot PQ \\cdot RS$, which halves the correct answer. The distractor $\\sqrt{10}$ results from incorrectly computing $\\sqrt{PR + QR} = \\sqrt{4 + 6} = \\sqrt{10}$. The distractor $\\frac{24\\sqrt{13}}{13}$ results from omitting the $\\frac{1}{2}$ in the first area expression, using area $= PR \\cdot QR = 24$, which doubles the correct answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM265L0L7', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'If $f(x) = 3 \\cdot 2^x$, what is the value of $f(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$30$"},{"key":"B","text":"$48$"},{"key":"C","text":"$96$"},{"key":"D","text":"$160$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substitute $x = 5$: $f(5) = 3 \\cdot 2^5 = 3 \\cdot 32 = 96$. The distractor $30$ results from computing $3 \\cdot 2 \\cdot 5 = 30$, treating the expression as linear multiplication rather than exponentiation. The distractor $48$ results from computing $3 \\cdot 2^4 = 48$, using $4$ as the exponent instead of $5$. The distractor $160$ results from computing $5 \\cdot 2^5 = 160$, swapping the coefficient and the input value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM274LAZR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In a $30°$-$60°$-$90°$ triangle, the side opposite the $60°$ angle has length $7\\sqrt{3}$. What is the length of the hypotenuse?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14', ARRAY['14'], E'In a $30°$-$60°$-$90°$ triangle, the sides are in the ratio $1 : \\sqrt{3} : 2$. The side opposite the $60°$ angle corresponds to $\\sqrt{3}$ times the shorter leg. So $\\sqrt{3} \\cdot s = 7\\sqrt{3}$, giving $s = 7$ (the shorter leg, opposite $30°$). The hypotenuse is $2s = 2 \\cdot 7 = 14$. A common error is confusing which side is opposite which angle — for instance, treating $7\\sqrt{3}$ as the hypotenuse and computing the shorter leg as $7\\sqrt{3}/2$. Another error is multiplying $7\\sqrt{3}$ by $2$ to get $14\\sqrt{3}$, which mistakes the given side for the shorter leg.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27PBQN6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A set of 40 custom game cards contains 11 red attack cards, 7 red defense cards, 13 blue attack cards, and 9 blue defense cards. Two cards are drawn at random without replacement. What is the probability that both cards drawn are red attack cards?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{110}{1600}$"},{"key":"B","text":"$\\frac{121}{1600}$"},{"key":"C","text":"$\\frac{11}{40}$"},{"key":"D","text":"$\\frac{11}{156}$"}]$lyceon_json$::jsonb, 'D', NULL, E'When drawing without replacement, the probability that the first card is a red attack card is $\\frac{11}{40}$, and the probability that the second card is also a red attack card, given the first was, is $\\frac{10}{39}$. Multiplying: $\\frac{11}{40} \\times \\frac{10}{39} = \\frac{110}{1560} = \\frac{11}{156}$. The distractor $\\frac{110}{1600}$ results from correctly computing $11 \\times 10 = 110$ in the numerator but incorrectly using $40 \\times 40 = 1600$ in the denominator instead of $40 \\times 39 = 1560$, failing to account for the reduced pool on the second draw. The distractor $\\frac{121}{1600}$ treats the draws as independent with replacement, computing $\\left(\\frac{11}{40}\\right)^2 = \\frac{121}{1600}$. The distractor $\\frac{11}{40}$ computes only the probability of drawing one red attack card on the first draw and stops, ignoring the second draw entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28LZG91', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'Lines $m$ and $n$ are parallel, and a transversal intersects line $m$ at point $A$ and line $n$ at point $B$. Point $C$ is on line $n$ (on the opposite side of $B$ from the transversal) so that $\\triangle ABC$ is formed. If $\\angle BAC = 37°$, $\\angle ABC = (2x + 11)°$, and $\\angle ACB = (3x - 8)°$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '28', ARRAY['28'], E'The sum of the interior angles of a triangle is $180°$. Setting up the equation: $37 + (2x + 11) + (3x - 8) = 180$. Combining like terms: $5x + 40 = 180$. Solving: $5x = 140$, so $x = 28$. A common error is forgetting to combine the constant terms correctly — for example, computing $37 + 11 + 8 = 56$ (adding $8$ instead of subtracting) to get $5x + 56 = 180$, yielding $x = 24.8$. Another error is setting the equation to $360°$ instead of $180°$, giving $5x + 40 = 360$ and $x = 64$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28Q6HAK', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the following system of equations have no solution?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM295C46T', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'A triangle has an exterior angle of $131°$ at one vertex. If one of the two non-adjacent interior angles measures $58°$, what is the measure, in degrees, of the other non-adjacent interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$49°$"},{"key":"B","text":"$73°$"},{"key":"C","text":"$83°$"},{"key":"D","text":"$122°$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Exterior Angle Theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. So $131° = 58° + x$, giving $x = 131° - 58° = 73°$. The distractor $49°$ results from incorrectly computing $180° - 131° = 49°$, treating the exterior angle as supplementary to the unknown non-adjacent angle rather than applying the Exterior Angle Theorem. The distractor $83°$ comes from an arithmetic slip, subtracting $131 - 48 = 83$ instead of $131 - 58 = 73$ (misreading $58$ as $48$). The distractor $122°$ results from computing $180° - 58° = 122°$, applying the supplementary-angle relationship to the known interior angle while ignoring the exterior angle entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29ZRG80', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = ax + b$, where $a$ and $b$ are constants. If $f(3) = 29$ and $f(11) = 77$, what is $f(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$11$"},{"key":"C","text":"$26$"},{"key":"D","text":"$47$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope is $a = \\frac{77 - 29}{11 - 3} = \\frac{48}{8} = 6$. Substituting into $f(3) = 29$: $6(3) + b = 29$, so $18 + b = 29$ and $b = 11$. Therefore $f(0) = 6(0) + 11 = 11$. The value $6$ results from finding the slope correctly but reporting $a$ instead of $f(0) = b$. The value $26$ results from subtracting $3$ from $f(3)$ directly ($29 - 3 = 26$) instead of subtracting $3$ times the slope. The value $47$ results from a sign error when finding $b$: using slope $-6$ instead of $6$, giving $-18 + b = 29$ and $b = 47$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AXRV5D', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company conducted a double-blind randomized controlled trial with 500 participants to test a new migraine medication. Participants were randomly assigned to receive either the medication or a placebo. After 12 weeks, $67\\%$ of participants in the medication group reported fewer migraines, compared to $41\\%$ in the placebo group. The difference was statistically significant at the $p < 0.01$ level. Which of the following conclusions is best supported by the study design and results?', NULL, $lyceon_json$[{"key":"A","text":"The medication is likely effective for all people who suffer from migraines, regardless of age or health status."},{"key":"B","text":"The reduction in migraines can be attributed to the medication rather than to other factors."},{"key":"C","text":"Because the $p$-value is less than $0.01$, there is less than a $1\\%$ chance the medication is ineffective."},{"key":"D","text":"Each participant who took the medication experienced a $26$ percentage point reduction in migraine frequency."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the study used random assignment, a placebo control, and double-blinding, differences between groups can be attributed to the treatment rather than confounding factors. The statistically significant result supports a causal conclusion that the medication reduced migraines relative to the placebo. The distractor about effectiveness for all people overgeneralizes — the study''s results apply to the population from which participants were sampled, not necessarily to every demographic group regardless of age or health. The distractor about the $p$-value misinterprets its meaning: a $p < 0.01$ means there is less than a $1\\%$ probability of observing a difference this large or larger if the medication had no effect (under the null hypothesis), not that there is less than a $1\\%$ chance the medication is ineffective. The distractor about a $26$ percentage point reduction per participant confuses a group-level difference ($67\\% - 41\\% = 26$ percentage points between groups) with an individual-level effect; individual responses varied, and the $26$ points describes the gap between group proportions, not any single person''s change.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
