INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BWKKTT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A survey of 200 randomly selected voters in a town found that $58\\%$ support a proposed park expansion. The margin of error for the survey is $4$ percentage points. Which of the following is the best interpretation of the margin of error?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $58\\%$ of all voters in the town support the park expansion."},{"key":"B","text":"Between $54\\%$ and $62\\%$ of the voters in the sample support the park expansion."},{"key":"C","text":"It is plausible that between $54\\%$ and $62\\%$ of all voters in the town support the park expansion."},{"key":"D","text":"At most $62\\%$ of all voters in the town support the park expansion."}]$lyceon_json$::jsonb, 'C', NULL, E'The margin of error creates a confidence interval around the sample statistic to estimate the population parameter. Since $58\\% \\pm 4\\%$ gives the interval $54\\%$ to $62\\%$, it is plausible that the true proportion of all voters who support the expansion falls within this range. The distractor stating exactly $58\\%$ of all voters support the expansion treats the sample statistic as the exact population parameter, ignoring sampling variability. The distractor stating the interval applies to the sample misapplies the margin of error — the sample result is already known to be $58\\%$; the interval estimates the unknown population proportion. The distractor stating at most $62\\%$ captures only the upper bound and ignores that the true proportion could also be below $58\\%$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 55, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DAQ012', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are taken to estimate mean commute times. Sample A consists of 85 commuters from City X, yielding a mean of $34$ minutes with a margin of error of $3$ minutes. Sample B consists of 110 commuters from City Y, yielding a mean of $29$ minutes with a margin of error of $2.5$ minutes. Both intervals are at the $95\\%$ confidence level. Which conclusion is most justified?', NULL, $lyceon_json$[{"key":"A","text":"The mean commute time in City X is definitively longer than in City Y because $34 > 29$."},{"key":"B","text":"Because the confidence intervals overlap, there is no evidence of a difference in mean commute times."},{"key":"C","text":"It is plausible that the mean commute time in City X exceeds that in City Y, but the overlapping intervals prevent a definitive conclusion."},{"key":"D","text":"The difference in sample means is $5$ minutes, which is within the combined margin of $5.5$ minutes, so the population means must be equal."}]$lyceon_json$::jsonb, 'C', NULL, E'The confidence interval for City X is $31$ to $37$ minutes, and for City Y it is $26.5$ to $31.5$ minutes. These intervals overlap (both include values near $31$), so we cannot definitively conclude the population means differ. However, the sample means do suggest a plausible difference, meaning it is reasonable — but not certain — that City X has a longer mean commute. The distractor claiming the mean is definitively longer ignores sampling variability entirely and treats sample means as population parameters. The distractor stating there is no evidence of a difference overstates what overlap implies — overlapping confidence intervals do not prove the means are the same; they only indicate we lack strong evidence to declare them different. The distractor concluding the means must be equal because $5 < 5.5$ incorrectly treats a simple comparison of the difference to the summed margins as proof of equality; this is not how hypothesis testing works, and summing margins this way does not produce a valid test statistic.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DNKJU8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher models the relationship between hours of sunlight per day, $x$, and average daily temperature in degrees Fahrenheit, $y$, using the line of best fit $y = 3.1x + 8.4$. On a day with $7$ hours of sunlight, the actual average temperature was $32°\\text{F}$. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"$-1.9$"},{"key":"B","text":"$1.9$"},{"key":"C","text":"$21.7$"},{"key":"D","text":"$30.1$"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted temperature is $y = 3.1(7) + 8.4 = 21.7 + 8.4 = 30.1°\\text{F}$. The residual is the actual value minus the predicted value: $32 - 30.1 = 1.9$. The answer $-1.9$ reverses the subtraction order, computing predicted minus actual ($30.1 - 32$) instead of actual minus predicted. The answer $21.7$ is only the product $3.1 \\times 7$, stopping partway through the predicted value calculation without adding the $y$-intercept. The answer $30.1$ is the predicted temperature itself, not the difference between actual and predicted values.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EKU14R', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'The population of a town increased by $15\\%$ from 2020 to 2021 and then decreased by $20\\%$ from 2021 to 2022. If the town''s population in 2022 was $11{,}960$, what was the population in 2020?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13000', ARRAY['13000'], E'Let $P$ be the 2020 population. After a $15\\%$ increase, the 2021 population is $1.15P$. After a $20\\%$ decrease, the 2022 population is $1.15P \\times 0.80 = 0.92P$. Setting $0.92P = 11{,}960$ gives $P = \\frac{11{,}960}{0.92} = 13{,}000$. The 2020 population was $13{,}000$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FT3LNX', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'If $3x^2 - 75 = 0$ and $x > 0$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Add 75 to both sides: $3x^2 = 75$. Divide both sides by 3: $x^2 = 25$. Taking the square root gives $x = \\pm 5$. Since the problem states $x > 0$, the answer is $x = 5$. A common error is giving $-5$, which satisfies the equation but violates the positive constraint. Another error is dividing 75 by 3 incorrectly to get $x^2 = 15$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GLWY3A', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line in the $xy$-plane passes through the points $(3, 17)$ and $(7, 41)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-1', ARRAY['-1'], E'The slope of the line is $\\frac{41 - 17}{7 - 3} = \\frac{24}{4} = 6$. Using point-slope form with $(3, 17)$: $y - 17 = 6(x - 3)$, which gives $y = 6x - 18 + 17 = 6x - 1$. The $y$-intercept is $-1$. A common error is computing the slope as $\\frac{41 + 17}{7 + 3}$, which would give a different result. Another error is finding the slope correctly but substituting the point coordinates incorrectly into the point-slope formula.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GZBSEN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'At a high school with $400$ students, $35\\%$ participate in a music program. Of the students in the music program, $25\\%$ also participate in the drama club. How many students participate in both the music program and the drama club?', NULL, $lyceon_json$[{"key":"A","text":"$28$"},{"key":"B","text":"$35$"},{"key":"C","text":"$100$"},{"key":"D","text":"$140$"}]$lyceon_json$::jsonb, 'B', NULL, E'First, $35\\%$ of $400$ is $0.35 \\times 400 = 140$ students in the music program. Then $25\\%$ of those $140$ is $0.25 \\times 140 = 35$ students in both programs. The answer $28$ results from computing $140 \\times 0.20 = 28$, using $20\\%$ instead of $25\\%$. The answer $100$ results from applying $25\\%$ to the total $400$ students ($0.25 \\times 400 = 100$) instead of to the music program participants. The answer $140$ stops after computing $35\\%$ of $400$ without applying the second percentage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IZS40E', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What are the solutions to $3x^2 + 11x - 4 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = \\frac{1}{3}$ and $x = -4$"},{"key":"B","text":"$x = -\\frac{1}{3}$ and $x = 4$"},{"key":"C","text":"$x = 3$ and $x = -4$"},{"key":"D","text":"$x = \\frac{4}{3}$ and $x = -1$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the quadratic: $3x^2 + 11x - 4 = (3x - 1)(x + 4) = 0$. Setting each factor to zero: $3x - 1 = 0$ gives $x = \\frac{1}{3}$, and $x + 4 = 0$ gives $x = -4$. To verify: $3(\\frac{1}{3})^2 + 11(\\frac{1}{3}) - 4 = \\frac{1}{3} + \\frac{11}{3} - 4 = 4 - 4 = 0$ and $3(16) + 11(-4) - 4 = 48 - 44 - 4 = 0$. The distractor $x = -\\frac{1}{3}$ and $x = 4$ results from reversing both signs of the correct solutions. The distractor $x = 3$ and $x = -4$ results from taking the reciprocal of $\\frac{1}{3}$, confusing the coefficient with the root. The distractor $x = \\frac{4}{3}$ and $x = -1$ results from incorrectly grouping the factorization as $(3x - 4)(x + 1)$, which expands to $3x^2 - x - 4$, not the original equation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JV58HO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A triangle has a base of $14$ centimeters and a height of $9$ centimeters. What is the area, in square centimeters, of the triangle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '63', ARRAY['63'], E'The area of a triangle is $\\frac{1}{2} \\cdot \\text{base} \\cdot \\text{height} = \\frac{1}{2}(14)(9) = \\frac{126}{2} = 63$ square centimeters. A common error is forgetting the $\\frac{1}{2}$ factor and computing $14 \\times 9 = 126$. Another error is computing the perimeter or a related quantity instead of the area.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K26IJ0', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'The system of equations $y = x^2 + 2x + k$ and $y = 6x - 7$ has exactly one solution. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-3', ARRAY['-3'], E'Setting the two expressions for $y$ equal: $x^2 + 2x + k = 6x - 7$, which simplifies to $x^2 - 4x + (k + 7) = 0$. For exactly one solution, the discriminant must equal zero: $(-4)^2 - 4(1)(k + 7) = 0$, so $16 - 4k - 28 = 0$, giving $-4k = 12$ and $k = -3$. A common error is forgetting to move the $-7$ to the left side, which would yield $16 - 4k = 0$ and $k = 4$. Another error is setting the discriminant greater than zero instead of equal to zero, which gives a range rather than a specific value.', NULL, NULL, 'draft', 1, 115, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KLRJMH', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'A linear function $h$ satisfies $h(2) = 19$ and $h(5) = 37$. What is the rate of change of $h$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'The rate of change of a linear function is the slope, computed as $\\frac{h(5) - h(2)}{5 - 2} = \\frac{37 - 19}{3} = \\frac{18}{3} = 6$. A common error is to reverse the subtraction order in the numerator or denominator but not both, which would change the sign. Another error is to divide one output value by its input (e.g., $\\frac{37}{5}$) instead of computing the difference quotient.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KWC7MF', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3x^4 \\cdot 7x^3$?', NULL, $lyceon_json$[{"key":"A","text":"$10x^7$"},{"key":"B","text":"$21x^7$"},{"key":"C","text":"$21x^{12}$"},{"key":"D","text":"$21x^4$"}]$lyceon_json$::jsonb, 'B', NULL, E'To multiply monomials, multiply the coefficients and add the exponents of like bases: $3 \\cdot 7 = 21$ and $x^4 \\cdot x^3 = x^{4+3} = x^7$, giving $21x^7$. The distractor $10x^7$ results from adding the coefficients ($3 + 7 = 10$) instead of multiplying them. The distractor $21x^{12}$ results from multiplying the exponents ($4 \\times 3 = 12$) instead of adding them, confusing the product rule with the power rule. The distractor $21x^4$ results from using only the larger exponent rather than summing both exponents.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LIZ1Z6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In a triangle, two of the interior angles measure $53°$ and $79°$. What is the measure, in degrees, of the third interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$26°$"},{"key":"B","text":"$48°$"},{"key":"C","text":"$52°$"},{"key":"D","text":"$132°$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of a triangle is $180°$. The third angle is $180° - 53° - 79° = 180° - 132° = 48°$. The distractor $26°$ results from subtracting the two given angles ($79° - 53° = 26°$) instead of using the triangle angle-sum property. The distractor $52°$ comes from an arithmetic slip, misadding $53 + 79$ as $128$ and computing $180 - 128 = 52$. The distractor $132°$ is the sum of the two given angles ($53° + 79° = 132°$), confusing the sum of two angles with the measure of the missing angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LMU0NL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A factory produces $16$ widgets per hour using $4$ machines, each operating at the same rate. The factory adds $3$ more machines, but due to reduced maintenance time, each machine''s production rate decreases by $25\\%$. How many widgets does the factory produce in $6$ hours with all $7$ machines operating?', NULL, $lyceon_json$[{"key":"A","text":"$72$"},{"key":"B","text":"$96$"},{"key":"C","text":"$126$"},{"key":"D","text":"$168$"}]$lyceon_json$::jsonb, 'C', NULL, E'Each machine originally produces $\\frac{16}{4} = 4$ widgets per hour. After the $25\\%$ rate reduction, each machine produces $4 \\times 0.75 = 3$ widgets per hour. With $7$ machines running for $6$ hours, total production is $7 \\times 3 \\times 6 = 126$ widgets. The answer $72$ comes from applying the reduced rate of $3$ widgets per hour to only the original $4$ machines ($4 \\times 3 \\times 6 = 72$), accounting for the rate decrease but not the additional machines. The answer $96$ uses the original $4$ machines at the original rate of $4$ widgets per hour ($4 \\times 4 \\times 6 = 96$), ignoring both changes entirely. The answer $168$ uses all $7$ machines but at the original rate ($7 \\times 4 \\times 6 = 168$), failing to apply the $25\\%$ rate reduction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LNT0Y7', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'A manufacturer produces gadgets that sell for $\\$19$ each. The fixed production cost is $\\$347$, and each gadget costs $\\$6$ to produce. What is the minimum number of whole gadgets that must be sold for the revenue to exceed the total production cost?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '27', ARRAY['27'], E'Revenue from selling $n$ gadgets is $19n$. The total production cost is $347 + 6n$. Setting revenue greater than cost gives $19n > 347 + 6n$, which simplifies to $13n > 347$, so $n > 26.69\\ldots$. Since $n$ must be a whole number, the minimum is $27$. A common error is to solve $19n > 347$ (ignoring the variable cost), giving $n > 18.26$ and answering $19$. Another error is to round $26.69$ down to $26$, which does not satisfy the strict inequality since $13(26) = 338 < 347$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N2BDYI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A teacher records the following test scores for $9$ students: $62$, $71$, $74$, $78$, $83$, $85$, $88$, $91$, $94$. A tenth student''s score is added, and the mean of all $10$ scores becomes $81$. What is the tenth student''s score?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '84', ARRAY['84'], E'The sum of the original $9$ scores is $62 + 71 + 74 + 78 + 83 + 85 + 88 + 91 + 94 = 726$. For the mean of $10$ scores to be $81$, the total sum must be $81 \\times 10 = 810$. Therefore, the tenth score is $810 - 726 = 84$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ND2HP7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A company surveyed 150 employees about their commute method and department. The results are shown in the table below.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NK197R', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A delivery service charges $\\$13$ per package plus a flat fee of $\\$29$. A customer has at most $\\$250$ to spend. Which inequality represents the number of packages $n$ the customer can have delivered?', NULL, $lyceon_json$[{"key":"A","text":"$13n + 29 \\leq 250$"},{"key":"B","text":"$13n + 29 \\geq 250$"},{"key":"C","text":"$29n + 13 \\leq 250$"},{"key":"D","text":"$13n - 29 \\leq 250$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is $13$ per package times $n$ packages plus the flat fee of $29$, giving $13n + 29$. Since the customer can spend at most $250$, the inequality is $13n + 29 \\leq 250$. Using $\\geq$ instead of $\\leq$ reverses the constraint, incorrectly requiring the cost to exceed the budget. Writing $29n + 13$ swaps the per-unit cost and the flat fee. Subtracting $29$ instead of adding it misidentifies the flat fee as a discount rather than an additional charge.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OVLZVJ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle in the $xy$-plane has the equation $(x + 2)^2 + (y - 7)^2 = 50$. A line with equation $y = x + 3$ intersects the circle at two points. What is the length of the chord formed by these two intersection points?', NULL, $lyceon_json$[{"key":"A","text":"$4\\sqrt{2}$"},{"key":"B","text":"$8\\sqrt{2}$"},{"key":"C","text":"$6\\sqrt{2}$"},{"key":"D","text":"$10\\sqrt{2}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circle has center $(-2, 7)$ and radius $\\sqrt{50} = 5\\sqrt{2}$. Rewrite the line as $x - y + 3 = 0$. The distance from the center to the line is $d = \\frac{|(-2) - 7 + 3|}{\\sqrt{1^2 + (-1)^2}} = \\frac{|-6|}{\\sqrt{2}} = \\frac{6}{\\sqrt{2}} = 3\\sqrt{2}$. The half-chord length is $\\sqrt{r^2 - d^2} = \\sqrt{50 - 18} = \\sqrt{32} = 4\\sqrt{2}$. The full chord length is $2 \\cdot 4\\sqrt{2} = 8\\sqrt{2}$. The distractor $4\\sqrt{2}$ results from computing the half-chord correctly but forgetting to double it. The distractor $6\\sqrt{2}$ results from a sign error in the distance formula, using $|-2 + 7 + 3| = 8$ instead of $|-2 - 7 + 3| = 6$, giving $d = 4\\sqrt{2}$, then $\\sqrt{50 - 32} = \\sqrt{18} = 3\\sqrt{2}$, and doubling to $6\\sqrt{2}$. The distractor $10\\sqrt{2}$ equals the diameter $2r = 2 \\cdot 5\\sqrt{2}$, which a student might use if they assume the line passes through the center.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OWTF4U', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'A line in the $xy$-plane is perpendicular to the line $2x - 5y = 15$ and passes through the point $(10, 3)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$-22$"},{"key":"B","text":"$-1$"},{"key":"C","text":"$7$"},{"key":"D","text":"$28$"}]$lyceon_json$::jsonb, 'D', NULL, E'Rewriting $2x - 5y = 15$ in slope-intercept form gives $y = \\frac{2}{5}x - 3$, so the slope is $\\frac{2}{5}$. The perpendicular slope is the negative reciprocal: $-\\frac{5}{2}$. Using point-slope form with $(10, 3)$: $y - 3 = -\\frac{5}{2}(x - 10)$, so $y = -\\frac{5}{2}x + 25 + 3 = -\\frac{5}{2}x + 28$. The $y$-intercept is $28$. The value $-22$ results from using $\\frac{5}{2}$ (reciprocal without negating) as the slope: $y = \\frac{5}{2}x - 25 + 3 = \\frac{5}{2}x - 22$. The value $-1$ results from using the original slope $\\frac{2}{5}$ instead of the perpendicular slope: $y = \\frac{2}{5}x - 4 + 3 = \\frac{2}{5}x - 1$. The value $7$ results from negating the slope but not taking the reciprocal, using $-\\frac{2}{5}$: $y = -\\frac{2}{5}x + 4 + 3 = -\\frac{2}{5}x + 7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PHGU1Z', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers wanted to determine whether a new fertilizer increases tomato yield. They divided 60 tomato plants into two groups of 30. Group 1 received the new fertilizer and was grown in a greenhouse, while Group 2 received no fertilizer and was grown outdoors. After 8 weeks, Group 1 had a higher average yield. Which of the following is the most significant flaw in the study design?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of 60 plants is insufficient to draw any conclusions."},{"key":"B","text":"The growing environment differs between the two groups, creating a confounding variable that prevents attributing the yield difference to the fertilizer alone."},{"key":"C","text":"The researchers should have measured yield after 4 weeks rather than 8 weeks."},{"key":"D","text":"The study would have been more reliable if three treatment groups had been used instead of two."}]$lyceon_json$::jsonb, 'B', NULL, E'The critical flaw is that the growing environment (greenhouse vs. outdoors) differs between the two groups. Because both the fertilizer and the environment changed simultaneously, any observed yield difference could be due to the greenhouse conditions rather than the fertilizer. This confounding variable makes it impossible to isolate the fertilizer''s effect. The distractor about sample size misidentifies the problem — 60 plants can be sufficient for detecting treatment effects; the issue is confounding, not power. The distractor about measurement timing addresses an irrelevant aspect of the study; changing the duration does not resolve the confounding between environment and treatment. The distractor about three groups does not address the core confounding issue — adding a third group without controlling the environment would perpetuate the same design flaw.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PQ9SW7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A school administrator notices that students who eat breakfast in the school cafeteria tend to have higher scores on standardized tests than students who skip breakfast. The administrator concludes that eating breakfast in the cafeteria causes higher test scores. Which of the following best explains why this conclusion may not be valid?', NULL, $lyceon_json$[{"key":"A","text":"The sample of students may have been too small to detect a difference."},{"key":"B","text":"The study is observational, so a cause-and-effect relationship cannot be established."},{"key":"C","text":"The standardized test may not accurately measure student knowledge."},{"key":"D","text":"The administrator should have compared students across multiple schools."}]$lyceon_json$::jsonb, 'B', NULL, E'The administrator observed an association between cafeteria breakfast and test scores but did not randomly assign students to eat or skip breakfast. Because the study is observational, confounding variables — such as socioeconomic status, sleep habits, or overall engagement — could explain the difference in scores. Without random assignment, a causal claim is not warranted. The distractor about sample size addresses statistical power but does not resolve the fundamental inability of observational studies to establish causation. The distractor about test accuracy questions the validity of the measurement instrument, which is unrelated to whether the observed association is causal. The distractor about comparing multiple schools concerns external validity and generalizability, not the causal inference problem inherent to observational data.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PTOAGB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 + 8x - 14y + 40 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Complete the square for both variables. Group terms: $(x^2 + 8x) + (y^2 - 14y) = -40$. Complete the square: $(x^2 + 8x + 16) + (y^2 - 14y + 49) = -40 + 16 + 49$. This gives $(x + 4)^2 + (y - 7)^2 = 25$. The standard form $(x - h)^2 + (y - k)^2 = r^2$ shows that $r^2 = 25$, so $r = 5$. A common error is forgetting to add the completing-the-square constants to the right side, yielding an incorrect radius. Another error is computing $r^2 = 25$ correctly but reporting $r = 25$ instead of $r = 5$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q7JBCU', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of length $6$ and $7$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{13}$"},{"key":"B","text":"$13$"},{"key":"C","text":"$\\sqrt{43}$"},{"key":"D","text":"$\\sqrt{85}$"}]$lyceon_json$::jsonb, 'D', NULL, E'By the Pythagorean Theorem, the hypotenuse $c$ satisfies $c^2 = 6^2 + 7^2 = 36 + 49 = 85$, so $c = \\sqrt{85}$. The distractor $\\sqrt{13}$ results from subtracting the squares ($49 - 36 = 13$) instead of adding them. The distractor $13$ comes from adding the leg lengths directly ($6 + 7 = 13$) without applying the Pythagorean Theorem. The distractor $\\sqrt{43}$ results from squaring only one leg: $36 + 7 = 43$, forgetting to square the second leg.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QPOBXS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set has the values $4$, $8$, $11$, $14$, $14$, $17$, $22$, $26$. What is the interquartile range (IQR) of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$10$"},{"key":"C","text":"$14$"},{"key":"D","text":"$22$"}]$lyceon_json$::jsonb, 'B', NULL, E'With $8$ values sorted, the lower half is $4, 8, 11, 14$ and the upper half is $14, 17, 22, 26$. The first quartile $Q_1 = \\frac{8 + 11}{2} = 9.5$ and the third quartile $Q_3 = \\frac{17 + 22}{2} = 19.5$. The IQR is $Q_3 - Q_1 = 19.5 - 9.5 = 10$. The answer $6$ comes from computing $14 - 8 = 6$, finding the difference between two adjacent values near the center rather than the quartiles. The answer $14$ is the median of the data set ($\\frac{14 + 14}{2} = 14$), not the IQR. The answer $22$ is the range ($26 - 4 = 22$), confusing the full range with the interquartile range.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RHEP1Q', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $125p^3 - 64q^3$?', NULL, $lyceon_json$[{"key":"A","text":"$(5p - 4q)(25p^2 - 20pq + 16q^2)$"},{"key":"B","text":"$(5p + 4q)(25p^2 - 20pq + 16q^2)$"},{"key":"C","text":"$(5p - 4q)(25p^2 + 20pq + 16q^2)$"},{"key":"D","text":"$(5p - 4q)(5p^2 + 20pq + 16q^2)$"}]$lyceon_json$::jsonb, 'C', NULL, E'This is a difference of cubes: $125p^3 = (5p)^3$ and $64q^3 = (4q)^3$. The difference of cubes formula is $a^3 - b^3 = (a - b)(a^2 + ab + b^2)$. With $a = 5p$ and $b = 4q$: $(5p - 4q)((5p)^2 + (5p)(4q) + (4q)^2) = (5p - 4q)(25p^2 + 20pq + 16q^2)$. The distractor $(5p - 4q)(25p^2 - 20pq + 16q^2)$ uses the wrong sign on the middle term, confusing the pattern with a perfect-square trinomial. The distractor $(5p + 4q)(25p^2 - 20pq + 16q^2)$ applies the sum of cubes formula $a^3 + b^3 = (a + b)(a^2 - ab + b^2)$ instead of the difference of cubes. The distractor $(5p - 4q)(5p^2 + 20pq + 16q^2)$ fails to square $5p$ in the first term of the trinomial, writing $5p^2$ instead of $25p^2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
