INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2STP8VU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'grid_in', E'A bookstore offers a discount of $\\$9$ on a book. If this discount represents $12\\%$ of the book''s original price, what is the original price of the book, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '75', ARRAY['75'], E'Let $p$ be the original price. Then $0.12p = 9$, so $p = \\frac{9}{0.12} = 75$. The original price of the book is $\\$75$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SYP6H3', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 8x - 23$. What is the value of $g(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$-8$"},{"key":"B","text":"$33$"},{"key":"C","text":"$56$"},{"key":"D","text":"$79$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 7$: $g(7) = 8(7) - 23 = 56 - 23 = 33$. The value $-8$ results from adding $8$ and $7$ instead of multiplying, then subtracting $23$: $8 + 7 - 23 = -8$. The value $56$ results from computing $8 \\times 7 = 56$ but stopping before subtracting $23$. The value $79$ results from adding $23$ instead of subtracting it: $56 + 23 = 79$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TYL36D', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $4$ inches and a height of $11$ inches. What is the volume of the cylinder, in cubic inches?', NULL, $lyceon_json$[{"key":"A","text":"$44\\pi$"},{"key":"B","text":"$88\\pi$"},{"key":"C","text":"$176\\pi$"},{"key":"D","text":"$704\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi(4^2)(11) = \\pi(16)(11) = 176\\pi$ cubic inches. The distractor $44\\pi$ results from using the formula $\\pi r h$ (forgetting to square the radius): $\\pi(4)(11) = 44\\pi$. The distractor $88\\pi$ results from using the lateral surface area formula $2\\pi r h = 2\\pi(4)(11) = 88\\pi$ instead of the volume formula. The distractor $704\\pi$ results from using the diameter ($8$) instead of the radius: $\\pi(8^2)(11) = \\pi(64)(11) = 704\\pi$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V3ZS9C', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The graph of $f(x) = a(x - h)^2 + k$ passes through the points $(1, 17)$ and $(5, 17)$, and has a minimum value of $-7$. What is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$3$"},{"key":"C","text":"$6$"},{"key":"D","text":"$24$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $f(1) = f(5) = 17$, the axis of symmetry is at $x = \\frac{1 + 5}{2} = 3$, so $h = 3$. The minimum value of the function is $k = -7$. Substituting the point $(1, 17)$ into $f(x) = a(x - 3)^2 - 7$: $17 = a(1 - 3)^2 - 7 = 4a - 7$, so $4a = 24$ and $a = 6$. The distractor $-6$ results from assuming the parabola has a maximum instead of a minimum, leading to $a = -6$, but since the function has a minimum, $a$ must be positive. The distractor $3$ results from using $h = 3$ directly as the value of $a$ or from computing $(1 - 3) = -2$ and dividing $24$ by $(-2)^3 = -8$ through an exponent error. The distractor $24$ results from solving $4a = 24$ but reporting $24$ instead of dividing by $4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VGGPFZ', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'At a farm stand, $3$ cartons of strawberries and $2$ baskets of blueberries cost $\\$29$, and $1$ carton of strawberries and $4$ baskets of blueberries cost $\\$23$. What is the total cost, in dollars, of $1$ carton of strawberries and $1$ basket of blueberries?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Let $s$ represent the cost of one carton of strawberries and $b$ represent the cost of one basket of blueberries. The system is $3s + 2b = 29$ and $s + 4b = 23$. Multiplying the second equation by $3$ gives $3s + 12b = 69$. Subtracting the first equation: $(3s + 12b) - (3s + 2b) = 69 - 29$, so $10b = 40$ and $b = 4$. Substituting back: $s + 4(4) = 23$, so $s = 7$. The total cost of one carton and one basket is $7 + 4 = 11$. A common error is to find only one variable and report it as the answer (giving $7$ or $4$). Another error is to average the two totals, $\\frac{29 + 23}{2} = 26$, which does not answer the question asked.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WE1R85', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the values $17$, $21$, $23$, $29$, and $35$. What is the mean of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$23$"},{"key":"B","text":"$25$"},{"key":"C","text":"$27$"},{"key":"D","text":"$31.25$"}]$lyceon_json$::jsonb, 'B', NULL, E'The mean is $\\frac{17 + 21 + 23 + 29 + 35}{5} = \\frac{125}{5} = 25$. The answer $23$ is the median (the middle value of the sorted data), not the mean. The answer $27$ results from an arithmetic error in summing the values (e.g., obtaining $135$ instead of $125$). The answer $31.25$ results from dividing the sum $125$ by $4$ instead of $5$, miscounting the number of data values.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XB1NQZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $11$ and a central angle of $60°$. What is the length of the arc intercepted by this central angle?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{11\\pi}{6}$"},{"key":"B","text":"$\\frac{11\\pi}{3}$"},{"key":"C","text":"$\\frac{22\\pi}{3}$"},{"key":"D","text":"$\\frac{11}{3}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Arc length equals $\\frac{\\theta}{360°} \\cdot 2\\pi r = \\frac{60}{360} \\cdot 2\\pi(11) = \\frac{1}{6} \\cdot 22\\pi = \\frac{22\\pi}{6} = \\frac{11\\pi}{3}$. The distractor $\\frac{11\\pi}{6}$ results from using $\\pi r$ instead of $2\\pi r$ in the arc-length formula, effectively halving the circumference. The distractor $\\frac{22\\pi}{3}$ results from using $120°$ instead of $60°$ as the central angle, doubling the correct arc length. The distractor $\\frac{11}{3}$ results from dropping the factor of $\\pi$ during computation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XK69IW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A bottling machine fills $47$ bottles in $4$ minutes. At this constant rate, how many minutes does it take to fill $329$ bottles?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '28', ARRAY['28'], E'The rate is $\\frac{47 \\text{ bottles}}{4 \\text{ minutes}}$. To find the time for $329$ bottles, set up the proportion $\\frac{47}{4} = \\frac{329}{t}$. Cross-multiplying gives $47t = 329 \\times 4 = 1316$, so $t = \\frac{1316}{47} = 28$ minutes.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
