INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YOEWFQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows a linear relationship between two variables. The line of best fit passes through the points $(2, 11)$ and $(8, 29)$. What is the slope of the line of best fit?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{3}$"},{"key":"B","text":"$3$"},{"key":"C","text":"$18$"},{"key":"D","text":"$-3$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope is $\\frac{29 - 11}{8 - 2} = \\frac{18}{6} = 3$. The answer $\\frac{1}{3}$ results from inverting the slope formula, computing $\\frac{\\Delta x}{\\Delta y}$ instead of $\\frac{\\Delta y}{\\Delta x}$. The answer $18$ comes from computing only the change in $y$ ($29 - 11 = 18$) without dividing by the change in $x$. The answer $-3$ applies an incorrect sign to the slope, as if the line were decreasing when both coordinates increase.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YOLRDT', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $3x - 7 > 14$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'D', NULL, E'Solving $3x - 7 > 14$ gives $3x > 21$, so $x > 7$. The value $8$ satisfies this because $3(8) - 7 = 17 > 14$. The value $5$ fails because $3(5) - 7 = 8$, which is not greater than $14$. The value $6$ fails because $3(6) - 7 = 11 < 14$. The value $7$ fails because $3(7) - 7 = 14$, which equals but is not greater than $14$ — a student choosing this confuses $>$ with $\\geq$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZVUNC8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'grid_in', E'A wildlife reserve has tagged 83 birds for tracking: 29 are hawks, 37 are finches, and 17 are owls. If one tagged bird is selected at random, what is the probability that it is an owl?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17/83', ARRAY['17/83', '0.204', '.204', '0.205', '.205'], E'The probability of selecting an owl is the number of owls divided by the total number of tagged birds: $\\frac{17}{83}$. A common error is dividing by the number of non-owl birds ($83 - 17 = 66$), giving $\\frac{17}{66}$, which incorrectly excludes owls from the denominator. Another error is confusing the count of hawks (29) or finches (37) with the count of owls.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20X7UWL', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Sociologist Priya Chandrasekaran studied how residents of a rapidly gentrifying neighborhood in Chennai, India, responded to the construction of a new luxury shopping complex on a site that had previously housed a weekly open-air vegetable market. Chandrasekaran found that long-term residents did not simply mourn the market''s disappearance; many redirected their purchasing to a smaller, less convenient market eleven blocks away. Notably, Chandrasekaran observed that these residents often bypassed closer retail options — including the new complex''s own grocery store, which offered comparable produce at similar prices. She argued that this behavior suggests the residents'' attachment to the open-air market format was not primarily about ________', $lyceon_json$[{"key":"A","text":"the affordability or accessibility of fresh produce but rather about preserving a communal social practice embedded in the market's informal structure."},{"key":"B","text":"the variety of goods available at the original market but rather about the architectural character of the market's physical space."},{"key":"C","text":"their resistance to urban development but rather about a pragmatic preference for shopping in less crowded environments."},{"key":"D","text":"nostalgia for the original market location but rather about a desire to support local farmers over corporate supply chains."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage notes that residents bypassed closer options offering comparable produce at similar prices to travel to a more distant open-air market. Since price and convenience were not the deciding factors, the attachment must stem from something intrinsic to the open-air market format itself. The completion about preserving a communal social practice embedded in the informal market structure logically accounts for why residents specifically sought out another open-air market rather than accepting equivalent goods from a different retail format. The option about architectural character focuses too narrowly on physical space and ignores the social dimension implied by the market''s communal format. The option about preferring less crowded environments contradicts the implied preference for the bustling open-air market format. The option about supporting local farmers over corporate supply chains introduces an economic motivation the passage does not address.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW214VXF6', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, marine biologist Sylvia Earle led an expedition to study bioluminescent organisms in the Mariana _______ the team discovered seventeen species previously unknown to science.', $lyceon_json$[{"key":"A","text":"Trench, and"},{"key":"B","text":"Trench and"},{"key":"C","text":"Trench,"},{"key":"D","text":"Trench"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses are being joined here: one about Earle leading an expedition and one about the team discovering new species. The choice using a comma followed by the coordinating conjunction ''and'' correctly joins these two independent clauses. The choice using only ''and'' without a comma creates a run-on when joining two independent clauses. The choice using only a comma creates a comma splice. The choice using no punctuation or conjunction creates a fused sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW224L3PF', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "tempered" most nearly mean?', E'The glassblower''s enthusiasm for her craft was tempered by an awareness of the economic realities facing independent artisans. While she remained passionate about creating hand-blown vessels, she increasingly accepted commissions for commercial projects to sustain her studio.', $lyceon_json$[{"key":"A","text":"moderated"},{"key":"B","text":"heated"},{"key":"C","text":"destroyed"},{"key":"D","text":"encouraged"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that the glassblower''s enthusiasm was tempered by economic awareness, meaning her excitement was moderated or restrained by practical concerns. The word "heated" reflects a different meaning of "temper" related to metallurgy and glasswork, but in this context the word describes an emotional restraint, not a physical process. "Destroyed" goes too far, since the passage says she remained passionate. "Encouraged" contradicts the passage''s indication that economic realities acted as a check on her enthusiasm, not a boost to it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW234DJQ8', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Paleontologist Jingmai O''Connor has argued that the small, feathered dinosaur Microraptor likely hunted in forested environments rather than open plains, citing the animal''s elongated hindlimb feathers as evidence of an arboreal lifestyle. Some researchers have challenged this interpretation, noting that similarly structured feathers appear in species whose fossils are found in arid, treeless deposits. ______ O''Connor maintains that feather morphology alone does not determine habitat and points to additional anatomical features — curved pedal claws and a flexible shoulder girdle — that collectively support an arboreal reconstruction for Microraptor.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Granted,"},{"key":"C","text":"Moreover,"},{"key":"D","text":"Regardless,"}]$lyceon_json$::jsonb, 'D', NULL, E'The passage presents a challenge to O''Connor''s position in the second sentence and then shows O''Connor maintaining her original claim despite that challenge. "Regardless" correctly signals that O''Connor''s response persists in the face of the objection. "In other words" would indicate a restatement of the preceding sentence, but O''Connor is not restating the critics'' point — she is pushing back against it. "Granted" would concede the critics'' point before countering, but the sentence after the blank does not concede anything; instead it broadens the evidential basis. "Moreover" adds a supporting point to the same argument, but the logical structure here is not cumulative — it is adversative, with O''Connor responding to an opposing view.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW235RFFI', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Geochemist Tariq al-Mansur analyzed isotopic ratios of strontium in tooth enamel from forty-seven individuals buried in a seventh-century necropolis near Córdoba, Spain. Because strontium isotope ratios in tooth enamel reflect the geological signature of the region where an individual lived during childhood, they can indicate whether a person grew up locally or migrated from elsewhere. Al-Mansur found that thirty-one individuals had strontium signatures consistent with the local geology, but sixteen displayed ratios matching geological formations found only in the Atlas Mountains of North Africa. Surprisingly, however, the burial positions, grave goods, and skeletal markers of nutritional status showed no systematic differences between the two groups. Al-Mansur argued that this uniformity suggests that by the seventh century, ________', $lyceon_json$[{"key":"A","text":"migrants from North Africa had been so thoroughly integrated into the local community that social distinctions based on geographic origin were no longer reflected in mortuary practices."},{"key":"B","text":"the necropolis had been used by two distinct communities that, despite different geographic origins, independently developed identical burial customs."},{"key":"C","text":"the strontium isotope method is unreliable for distinguishing between individuals from the Córdoba region and those from the Atlas Mountains."},{"key":"D","text":"the population of seventh-century Córdoba was predominantly composed of recent migrants from North Africa rather than long-established local residents."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that sixteen of forty-seven individuals grew up in a geologically distinct region (North Africa) yet were buried with the same positions, grave goods, and nutritional markers as those who grew up locally. The completion about thorough social integration logically explains why geographic origin left no trace in mortuary practices — the migrants had become indistinguishable from locals in social standing. The option about two distinct communities independently developing identical customs introduces an improbable coincidence that the passage does not suggest and contradicts the simpler integration explanation al-Mansur would propose. The option claiming the isotope method is unreliable contradicts the passage''s use of strontium analysis as a valid tool that successfully distinguished two populations. The option about a predominantly migrant population misreads the data: thirty-one of forty-seven individuals showed local signatures, meaning the majority grew up locally.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23CDTRH', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if accurate, would most effectively illustrate the claim about Tanizaki''s narrative technique?', E'Literary scholars have noted that Junichiro Tanizaki frequently employed an indirect narrative technique in his later novels: rather than depicting pivotal events directly, he presented them through the fragmented recollections of peripheral characters, each of whom possessed only a partial understanding of what had occurred. This approach, scholars argue, created a deliberate ambiguity that forced readers to construct meaning from incomplete and sometimes contradictory accounts.', $lyceon_json$[{"key":"A","text":"\"In The Key, Tanizaki uses diary entries from both husband and wife, each revealing secrets the other cannot know, so that the full truth emerges only in the gaps between their competing versions.\""},{"key":"B","text":"\"Tanizaki's prose style in The Makioka Sisters is characterized by extraordinarily long sentences that mirror the slow, unhurried passage of time in a traditional Osaka household.\""},{"key":"C","text":"\"Tanizaki's essay In Praise of Shadows is a meditation on Japanese aesthetics that rejects Western preferences for brightness and clarity in favor of subtlety and obscurity.\""},{"key":"D","text":"\"Critics often compare Tanizaki to Kawabata, but the two writers differ fundamentally in their approach to depicting female characters and domestic life.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Tanizaki''s technique of presenting events through fragmented, partial accounts from characters with incomplete knowledge, producing deliberate ambiguity. The quotation about The Key describes exactly this: diary entries from two characters each holding partial knowledge, with truth emerging from gaps between competing versions. The quotation about long sentences in The Makioka Sisters addresses prose style and pacing, not narrative indirection through multiple partial perspectives. The quotation about In Praise of Shadows concerns a nonfiction essay on aesthetics, which is unrelated to narrative technique in novels. The quotation comparing Tanizaki to Kawabata discusses critical reception and thematic differences, not the specific indirect narrative method the passage describes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW250NWNW', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1953, the architect Alison Smithson argued that postwar housing estates, despite their hygienic advantages over Victorian slums, failed to foster communal life because they eliminated the informal gathering spaces—stoops, alleyways, corner shops—that had sustained neighborhood bonds. Her critique was initially dismissed by planning authorities who pointed to measurable improvements in sanitation and square footage per resident. By the late 1960s, however, rising vandalism and tenant dissatisfaction on several estates lent empirical weight to Smithson''s contention, and planners began incorporating semi-public "streets in the sky" into tower-block designs.', $lyceon_json$[{"key":"A","text":"It presents a claim, describes the initial response to it, and then explains how subsequent events supported the claim."},{"key":"B","text":"It compares two architectural theories and evaluates which one has had greater influence on urban planning."},{"key":"C","text":"It describes a problem, proposes a solution, and then assesses the solution's effectiveness."},{"key":"D","text":"It traces the evolution of British housing policy from the Victorian era to the present day."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first presents Smithson''s claim that postwar estates failed to foster communal life, then describes how planning authorities initially dismissed it, and finally shows how later evidence from rising vandalism and tenant dissatisfaction supported her original contention. The option about comparing two architectural theories is inaccurate because the passage focuses on one architect''s claim and its reception, not a comparison of competing theories. The option describing a problem-solution-assessment structure mischaracterizes the text: while Smithson identifies a problem, the passage''s primary arc is about the trajectory of her claim from dismissal to validation, not an evaluation of a solution''s effectiveness. The option about tracing housing policy from Victorian times to the present overstates the passage''s chronological scope, which covers roughly 1953 to the late 1960s and does not survey Victorian policy or extend to the present.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW263RFQZ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Economist Raj Chetty''s large-scale study of economic mobility in the United States found that children who moved from low-opportunity neighborhoods to higher-opportunity ones before the age of thirteen experienced significant gains in lifetime earnings. The effect diminished sharply for those who moved after that age, suggesting a critical developmental window. ______ even among children who moved early, the gains varied substantially depending on the quality of local schools in the destination neighborhood, indicating that geographic relocation alone is insufficient without institutional support.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"In other words,"},{"key":"D","text":"By contrast,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence before the blank establishes one finding (the age-related critical window), and the sentence after the blank introduces an additional, complicating finding about the same group of early movers — that school quality also matters. "Furthermore" correctly signals the addition of a new, complementary finding that deepens the analysis. "Consequently" would indicate that the variation in gains is a direct result of the diminishing effect after age thirteen, but the sentence instead introduces an independent variable (school quality) rather than a consequence of the age threshold. "In other words" implies a restatement of the previous point, but the sentence introduces new information about school quality rather than rephrasing the age finding. "By contrast" suggests an opposing relationship, but the new finding does not contradict the earlier one; it supplements it with an additional layer.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26YUMWT', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'The fruit fly Drosophila melanogaster has been a staple of genetics research for over a century. Its genome was fully sequenced in the year 2000, revealing approximately 13,600 genes. <u>Many of those genes have counterparts in the human genome that are associated with diseases such as Parkinson''s and diabetes.</u> This genetic overlap has made the fruit fly invaluable for studying human health conditions in a controlled laboratory setting.', $lyceon_json$[{"key":"A","text":"It explains why the fruit fly's genome is relevant to human medical research."},{"key":"B","text":"It provides a historical overview of fruit fly genetics studies."},{"key":"C","text":"It challenges the assumption that fruit flies are useful research organisms."},{"key":"D","text":"It describes the process by which the fruit fly genome was sequenced."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence identifies shared genes between fruit flies and humans linked to specific diseases, thereby explaining the relevance of the fruit fly genome to human medical research. This connection directly supports the final sentence''s claim about the fly''s value for studying human health conditions. The option describing a historical overview misidentifies the function: the sentence is about genetic overlap, not the history of fruit fly research. The option about challenging assumptions contradicts the passage''s supportive tone toward fruit fly research. The option about sequencing processes is inaccurate because the underlined sentence discusses the content of the genome, not how it was sequenced.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27BJWEC', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research paper and wants to emphasize the contrast between the expected and actual outcomes of a scientific experiment. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'- Biologist Elara Kovacs conducted a 2023 study on the regenerative abilities of axolotls (Ambystoma mexicanum).
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28KWL0J', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing an essay about sustainable architecture and wants to acknowledge a limitation of rammed-earth construction while arguing that recent innovations have largely addressed it. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'- Rammed-earth construction compresses layers of damp soil, gravel, and stabilizers into dense walls.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW290TL8L', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Geochemist Clara Devereaux has argued that volcanic sediment layers in northern Iceland contain unusually high concentrations of rare-earth _______ other researchers have questioned whether her sampling methods adequately account for glacial redistribution of mineral deposits.', $lyceon_json$[{"key":"A","text":"elements; however,"},{"key":"B","text":"elements, however,"},{"key":"C","text":"elements; consequently,"},{"key":"D","text":"elements, and consequently,"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses present a contrast: Devereaux argues for high mineral concentrations, while other researchers question her methods. A semicolon correctly joins two independent clauses, and ''however'' accurately signals the contrasting relationship. The choice using a comma before ''however'' creates a comma splice, since ''however'' is a conjunctive adverb, not a coordinating conjunction. The choice using ''consequently'' with a semicolon is grammatically correct but logically wrong: the researchers'' skepticism is not a consequence of Devereaux''s argument but a counterpoint to it. The choice using ''and consequently'' with a comma similarly misrepresents the logical relationship as one of result rather than contrast.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BUX123', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists at the Farallon Institute have long studied the migration patterns of humpback whales along the Pacific coast. Their latest tracking data, gathered over a seventeen-month period, reveals that humpback whales are arriving at their northern feeding grounds nearly three weeks earlier than they did a decade ago. ______ the researchers attribute this shift primarily to rising sea-surface temperatures, which cause prey species such as krill and anchovies to concentrate in northern waters sooner each spring.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Meanwhile,"},{"key":"D","text":"Nevertheless,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence following the blank explains the cause behind the earlier arrival described in the previous sentence, making the relationship one of logical consequence. "Accordingly" correctly signals that the explanation follows from the observed data. "In contrast" wrongly implies an opposing relationship. "Meanwhile" suggests a simultaneous but unrelated event, which misreads the connection between the sentences. "Nevertheless" introduces a concession or contradiction that does not exist in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
