INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CDSO3A', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the passage as a whole?', E'Historian Lucinda Osei has argued that the nineteenth-century transatlantic cable networks did not merely transmit messages faster but fundamentally restructured how commodity traders perceived time itself. Before the cables, traders in Liverpool operated on what Osei calls "harvest time" — their decisions calibrated to seasonal rhythms of planting and reaping in distant colonies. A price quoted in March for cotton arriving in September carried inherent uncertainty, and traders built elaborate risk-sharing arrangements around this temporal gap.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CTCFOH', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the municipal planning committee convened in March 2024 to review proposals for the waterfront redevelopment, several architects _______ designs that incorporated floating gardens, a concept previously untested in the region.', $lyceon_json$[{"key":"A","text":"has presented"},{"key":"B","text":"presenting"},{"key":"C","text":"presented"},{"key":"D","text":"presents"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence establishes a past-tense context with ''convened in March 2024,'' so the verb in the main clause must also be in the simple past tense and agree with the plural subject ''architects.'' The choice ''presented'' correctly provides the simple past tense form. The choice ''has presented'' uses a singular auxiliary that does not agree with the plural subject ''architects'' and shifts to the present perfect tense without justification. The choice ''presenting'' is a participle, not a finite verb, so it leaves the main clause without a predicate. The choice ''presents'' is simple present tense and singular, conflicting with both the past-tense context and the plural subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DFJX04', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason that Holbrook''s categorization of Permian-era fungi proved controversial among paleontologists?', E'When mycologist Ren Holbrook proposed in 2017 that several fossilized structures found in Permian-era rock formations in Siberia were the fruiting bodies of a previously unknown fungal phylum, paleontologists objected. The structures, each roughly eleven centimeters across, bore superficial resemblance to known fungal fossils but lacked the microscopic cell-wall signatures that mycologists typically use to confirm fungal identity. Holbrook argued that the extreme heat and pressure of the surrounding sediment had obliterated these signatures while preserving the overall morphology. Critics countered that without cell-wall evidence, the structures could equally be the remains of colonial algae or degraded plant tissue, and that Holbrook''s preservation argument, while plausible, was unfalsifiable.', $lyceon_json$[{"key":"A","text":"The fossils were found in a geological region where fungal remains had never been documented before."},{"key":"B","text":"The fossils lacked the microscopic features that are normally used to verify that a structure is fungal in origin."},{"key":"C","text":"Holbrook was a mycologist rather than a trained paleontologist, which raised questions about disciplinary expertise."},{"key":"D","text":"The proposed fungal phylum would have required reclassifying several previously identified Permian-era species."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage explicitly states that the structures lacked the microscopic cell-wall signatures typically used to confirm fungal identity, and that critics argued without this cell-wall evidence, the structures could be algae or degraded plant tissue. The choice about missing microscopic features directly reflects this stated reason. The option about the geographical region introduces a claim not made in the passage. The option about disciplinary expertise infers a credibility concern that the passage never raises. The option about reclassifying other species introduces information entirely absent from the text.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E8HUHE', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "qualified" most nearly mean?', E'The observatory''s director offered a qualified endorsement of the new spectral analysis method. She acknowledged that the technique detected faint emission lines that older instruments missed, but she cautioned that its calibration protocol introduced systematic uncertainties exceeding 4.7 percent in certain wavelength ranges, making it unsuitable for precision radial-velocity measurements without further refinement.', $lyceon_json$[{"key":"A","text":"limited"},{"key":"B","text":"credentialed"},{"key":"C","text":"enthusiastic"},{"key":"D","text":"provisional"}]$lyceon_json$::jsonb, 'A', NULL, E'The director''s endorsement is described as qualified because she acknowledged the method''s strengths while also identifying specific limitations, meaning the endorsement was limited or given with reservations. "Credentialed" reflects a different meaning of "qualified" related to holding certifications, but the passage is not discussing the director''s credentials; it is describing the conditional nature of her support. "Enthusiastic" contradicts the passage, which emphasizes her cautions about systematic uncertainties. "Provisional" suggests the endorsement is temporary and subject to withdrawal, but the passage indicates her reservations are about inherent limitations in certain wavelength ranges rather than about a pending decision that might change over time; the endorsement is restricted in scope, not temporarily granted.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FJ3P0S', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Ethiopian distance runner Letesenbet Gidey, who broke the 10,000-meter world record in 2021 with a time of 29 minutes and 1.03 _______ also holds the world record in the half marathon, having completed the 2022 Valencia event in 1 hour, 2 minutes, and 52 seconds.', $lyceon_json$[{"key":"A","text":"seconds,"},{"key":"B","text":"seconds;"},{"key":"C","text":"seconds"},{"key":"D","text":"seconds, she"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence has one subject, ''Letesenbet Gidey,'' modified by a nonrestrictive relative clause (''who broke...seconds''). After the relative clause closes, the main verb ''also holds'' continues the original sentence. The comma after ''seconds'' correctly closes the nonrestrictive clause and allows the main predicate to resume. A semicolon would incorrectly split the sentence, separating the subject from its verb. Omitting punctuation entirely would fail to close the nonrestrictive clause. Adding ''she'' after a comma would create a new independent clause spliced onto the first, producing a comma splice and a redundant subject.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GX2S6M', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'A team of entomologists at the University of Brasilia hypothesized that the unusually high species diversity of beetles in the Serra da Canastra plateau is primarily driven by the region''s mosaic of microhabitats — small, distinct ecological zones created by variations in soil mineral content across short distances. According to this hypothesis, beetles with slightly different dietary needs can coexist in close proximity because each microhabitat supports a unique set of plant species that serve as food sources.', $lyceon_json$[{"key":"A","text":"Soil samples taken at intervals of fifty meters across the plateau reveal significant differences in concentrations of iron, manganese, and phosphorus."},{"key":"B","text":"The Serra da Canastra plateau receives more annual rainfall than most other plateaus in the same mountain range."},{"key":"C","text":"Beetle species found in the Serra da Canastra plateau are genetically similar to beetle species found in other regions of Brazil."},{"key":"D","text":"The total number of beetle species identified in the Serra da Canastra plateau has increased over the past decade due to improved surveying methods."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis attributes beetle diversity to a mosaic of microhabitats created by variations in soil mineral content. A finding that soil samples taken at short intervals show significant differences in mineral concentrations would directly confirm the existence of such microhabitats, supporting the hypothesis. The finding about rainfall addresses climate rather than soil composition and does not bear on microhabitat mosaics. The finding about genetic similarity to beetles in other regions is irrelevant to what drives diversity within the plateau. The finding about improved surveying methods explains a change in species counts over time but does not address the mechanism the hypothesis proposes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IUDCBC', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'A 2023 study by ornithologist Priya Chakraborty examined the nesting patterns of bar-tailed godwits along the coast of New _______ the birds, which migrate over 11,000 kilometers nonstop from Alaska, select nest sites based on soil moisture rather than proximity to food sources.', $lyceon_json$[{"key":"A","text":"Zealand. According to Chakraborty,"},{"key":"B","text":"Zealand, according to Chakraborty,"},{"key":"C","text":"Zealand; moreover, according to Chakraborty,"},{"key":"D","text":"Zealand; in other words, according to Chakraborty,"}]$lyceon_json$::jsonb, 'A', NULL, E'The first clause introduces the study, and the second clause presents a specific finding attributed to Chakraborty. These are two independent clauses, so a period correctly separates them while beginning a new sentence with the attribution. The choice using only a comma creates a comma splice between two independent clauses. The choice using a semicolon with ''moreover'' is grammatically acceptable for joining independent clauses, but ''moreover'' incorrectly signals that the second clause adds a further point beyond what was already stated, when in fact the second clause presents the study''s core finding rather than supplementary information. The choice using ''in other words'' falsely implies the second clause restates the first in different terms, when the two clauses convey distinct information.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L37CM4', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In 2019, marine biologist Anika Patel published findings from a seven-year study of ribbon eel populations along the southern coast of Mozambique. Patel discovered that ribbon eels, previously believed to be solitary creatures, actually form loose social clusters of four to nine individuals during the monsoon season. These clusters appear to coordinate hunting behaviors, with individual eels taking turns driving schools of small fish toward the group. Patel''s observations challenged the long-standing assumption that ribbon eels interact with members of their species only during mating.', $lyceon_json$[{"key":"A","text":"Ribbon eels are more effective hunters when they work together than when they hunt alone."},{"key":"B","text":"A researcher's study revealed that ribbon eels exhibit previously unrecognized social behaviors."},{"key":"C","text":"Marine biologists have historically underestimated the intelligence of ribbon eels."},{"key":"D","text":"Ribbon eel populations in Mozambique are larger than scientists had previously estimated."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage centers on Patel''s discovery that ribbon eels form social clusters and coordinate hunting, which contradicted the prior assumption that they interact only during mating. The choice stating that a researcher''s study revealed previously unrecognized social behaviors accurately captures this main idea. The option about hunting effectiveness makes a comparative claim not supported by the text, which describes coordinated hunting but never compares its effectiveness to solitary hunting. The option about underestimated intelligence goes beyond the passage''s scope, which addresses social behavior rather than intelligence. The option about population size misreads the passage entirely; the study concerned behavior, not population counts.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
