INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L6VQAR', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction to the ceramic art of the Moche civilization for readers unfamiliar with this culture. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'- The Moche civilization flourished along the northern coast of Peru from roughly 100 to 700 CE.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M9SJAC', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "plastic" most nearly mean?', E'Neuroscientists studying barn owls discovered that the auditory localization circuits in juvenile birds are remarkably plastic. When researchers fitted young owls with prismatic lenses that shifted visual input by 23 degrees, the birds recalibrated their auditory maps within eleven weeks to align sound localization with the displaced visual field.', $lyceon_json$[{"key":"A","text":"adaptable"},{"key":"B","text":"synthetic"},{"key":"C","text":"rigid"},{"key":"D","text":"transparent"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how juvenile owls recalibrated their auditory maps in response to shifted visual input, demonstrating that the circuits are adaptable or capable of being reshaped. "Synthetic" refers to artificial materials, which misapplies the everyday meaning of "plastic" as a manufactured substance rather than the scientific sense used here. "Rigid" is the opposite of what the passage describes, since the circuits changed in response to altered input. "Transparent" has no support in the passage and does not relate to the capacity for neural reorganization being discussed.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OAT4HK', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the late nineteenth century, the architect Rafael Guastavino emigrated from Spain to the United States, bringing with him a masonry technique known as thin-tile vaulting. This method, which uses interlocking layers of lightweight terracotta tiles, allows for the construction of self-supporting curved ceilings without temporary wooden scaffolding. ______ Guastavino''s technique proved especially valuable in public buildings such as subway stations and municipal halls, where large open spans were needed but traditional heavy stone vaults would have been prohibitively expensive.', $lyceon_json$[{"key":"A","text":"For instance,"},{"key":"B","text":"On the other hand,"},{"key":"C","text":"As a result,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'C', NULL, E'The second sentence establishes that thin-tile vaulting is lightweight and self-supporting, and the sentence after the blank describes a practical consequence of those properties: Guastavino''s technique was adopted for large public buildings where heavy stone vaults were too costly. "As a result" correctly signals this cause-and-effect relationship. "For instance" would introduce a specific example of the preceding claim rather than a consequence, misidentifying the rhetorical purpose. "On the other hand" implies a contrast that is not present. "Specifically" would narrow or elaborate on the same point rather than present an outcome, misreading the logical connection.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TQF9J8', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W79OSS', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Archaeobotanist Maren Solvik analyzed charred seed remains from a Bronze Age settlement in central Norway and found that the inhabitants cultivated both barley and a now-rare variety of oats. While barley can tolerate the region''s short growing season, it is highly susceptible to the fungal blight that thrives in Norway''s wet summers. The oat variety, by contrast, is blight-resistant but requires a slightly longer frost-free period to mature. Solvik concluded that by planting both crops, the settlement''s inhabitants ensured that ________', $lyceon_json$[{"key":"A","text":"at least one grain crop would likely survive to harvest regardless of whether a given summer was unusually wet or unusually short."},{"key":"B","text":"they could trade surplus grain with neighboring settlements that grew only a single crop species."},{"key":"C","text":"the nutritional diversity of their diet would exceed that of contemporary settlements in southern Scandinavia."},{"key":"D","text":"their farming techniques would be adopted by subsequent generations of farmers throughout the region."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that barley tolerates short seasons but is vulnerable to wet-summer blight, while the oat variety resists blight but needs a longer frost-free period. Growing both crops together means that in a wet summer barley might fail but oats would survive, and in a short summer oats might not mature but barley would. The completion stating that at least one crop would likely survive regardless of weather conditions follows logically from these complementary vulnerabilities. The option about trading surplus introduces an economic activity the passage never mentions. The option about nutritional diversity relative to southern Scandinavia introduces a comparison unsupported by the text. The option about techniques being adopted by future generations speculates about historical influence beyond what the passage addresses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WFOBLV', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of handwritten manuscripts at the university''s rare book archive _______ among the most significant holdings in the southeastern United States.', $lyceon_json$[{"key":"A","text":"remain"},{"key":"B","text":"remains"},{"key":"C","text":"have remained"},{"key":"D","text":"are remaining"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is ''collection,'' a singular noun, not the plural ''manuscripts'' in the prepositional phrase. A singular subject requires a singular verb form. The choice ''remains'' correctly provides the third-person singular present tense. The choice ''remain'' is a plural verb form that does not agree with the singular subject ''collection.'' The choice ''have remained'' uses a plural auxiliary (''have'') that does not agree with the singular subject. The choice ''are remaining'' similarly uses a plural auxiliary (''are'') and shifts to the present progressive tense without contextual justification.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XLNKKX', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Researchers at the Galápagos Science Center, _______ annual surveys of marine iguana populations since 2009, reported in their latest findings that juvenile survival rates have declined by nearly 37 percent over the past seven years.', $lyceon_json$[{"key":"A","text":"who have conducted"},{"key":"B","text":"having been conducting"},{"key":"C","text":"whom have conducted"},{"key":"D","text":"which conducted"}]$lyceon_json$::jsonb, 'A', NULL, E'The blank introduces a nonrestrictive relative clause modifying ''Researchers,'' which refers to people. The correct relative pronoun for people in the subject position is ''who,'' and ''have conducted'' correctly uses the present perfect to indicate an action begun in 2009 and continuing to the present. The choice ''having been conducting'' is a participial phrase that awkwardly uses the perfect progressive participle; while not always ungrammatical, it creates an unnecessarily convoluted construction and, more critically, is not a relative clause, so it cannot properly introduce the subordinate information set off by commas in this structure. The choice using ''whom'' is incorrect because ''whom'' is the objective case, but the pronoun here serves as the subject of ''have conducted.'' The choice using ''which'' is incorrect because ''which'' refers to things, not people, and ''Researchers'' are people.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y96TBP', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from Yoon''s study, if true, would most directly weaken the conventional explanation described in the text?', E'For decades, ornithologists explained the dramatic plumage color differences between male and female eclectus parrots — males are bright green while females are vivid red and blue — as a straightforward case of sexual selection: males evolved conspicuous coloring to attract mates. Biologist Ji-Won Yoon challenged this conventional explanation by proposing that the color difference instead evolved as an adaptation to each sex''s distinct nesting role. Males, who spend most of their time foraging in forest canopies, benefit from green plumage that camouflages them among leaves. Females, who defend scarce tree hollows against rival females and predatory snakes, benefit from bright warning coloration that signals their aggressive territorial presence.', $lyceon_json$[{"key":"A","text":"Female eclectus parrots with experimentally dulled plumage lost their nesting hollows to rival females at significantly higher rates than females with unaltered plumage."},{"key":"B","text":"Male eclectus parrots with brighter green plumage were observed to have higher survival rates in foraging areas with dense canopy cover."},{"key":"C","text":"In controlled mate-choice experiments, female eclectus parrots showed no measurable preference for males with more vivid green coloring over males with duller green coloring."},{"key":"D","text":"Eclectus parrot populations in regions with fewer natural predators displayed the same degree of sexual dichromatism as populations in predator-rich regions."}]$lyceon_json$::jsonb, 'C', NULL, E'The conventional explanation holds that male green plumage evolved through sexual selection — that is, females preferring brightly colored males. A finding that females show no preference for more vivid males directly undercuts this mechanism by removing the selective pressure the explanation depends on. The finding about females losing hollows when their plumage is dulled supports Yoon''s alternative explanation rather than weakening the conventional one. The finding about males with brighter green having higher survival in dense canopy also supports Yoon''s hypothesis about camouflage, not the sexual selection explanation. The finding about dichromatism persisting regardless of predator density is tangential; the conventional explanation concerns mate choice, not predation pressure, so predator-density data does not directly address the sexual selection claim.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YAVS7F', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the first?', E'Restoration ecologists have long assumed that reintroducing a keystone predator to a degraded ecosystem will trigger a trophic cascade that restores vegetation patterns. The textbook example is the return of wolves to Yellowstone in 1995: elk herds, no longer free to overgraze riverbanks, retreated from riparian zones, allowing willow and aspen to regenerate and stabilize stream channels.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YF072P', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the summit''s keynote speaker nor the three panelists who followed _______ willing to address the discrepancy between the organization''s published emissions targets and its actual carbon output for the preceding fiscal year.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"were"},{"key":"C","text":"has been"},{"key":"D","text":"being"}]$lyceon_json$::jsonb, 'B', NULL, E'In a ''neither...nor'' construction, the verb agrees with the subject closer to it. Here, the closer subject is ''the three panelists,'' which is plural, so the verb must be plural. The choice ''were'' correctly provides a plural past-tense form that agrees with ''panelists.'' The choice ''was'' is singular and would only be correct if the closer subject were singular. The choice ''has been'' is singular present perfect, failing on both number agreement and tense consistency with the past-tense context. The choice ''being'' is a participle that cannot serve as the main verb of the clause, leaving the sentence without a finite predicate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
